import React, { useState, useEffect } from 'react';
import { fetchFraudCycles, fetchFraudLogs } from '../services/api';

function parseArray(value) {
  if (Array.isArray(value)) return value;
  if (typeof value === 'string') {
    try {
      const parsed = JSON.parse(value);
      if (Array.isArray(parsed)) return parsed;
    } catch (_) {}
    if (value.includes('->')) return value.split('->').map((v) => v.trim()).filter(Boolean);
    if (value.includes('→')) return value.split('→').map((v) => v.trim()).filter(Boolean);
    if (value.startsWith('{') && value.endsWith('}')) {
      return value.slice(1, -1).split(',').map((v) => v.trim()).filter(Boolean);
    }
  }
  return [];
}

function getCyclePath(cycle) {
  return (
    parseArray(cycle?.cycle) ||
    parseArray(cycle?.cycle_path) ||
    parseArray(cycle?.loop_path) ||
    parseArray(cycle?.path) ||
    []
  );
}

function getTradePath(cycle) {
  return (
    parseArray(cycle?.trade_path) ||
    parseArray(cycle?.trade_ids) ||
    parseArray(cycle?.transactions) ||
    []
  );
}

function getTradeId(cycle) {
  return cycle?.trade_id ?? cycle?.root_trade_id ?? cycle?.id ?? '—';
}

function getStock(cycle) {
  return cycle?.symbol ?? cycle?.stock_symbol ?? cycle?.stock_id ?? '—';
}

function getDepth(cycle, loopPath, tradePath) {
  if (cycle?.depth != null) return cycle.depth;
  if (tradePath.length) return tradePath.length;
  if (loopPath.length) return Math.max(0, loopPath.length - 1);
  return '—';
}

function getConfidence(cycle, loopPath) {
  if (cycle?.confidence != null) return cycle.confidence;
  if (loopPath.length >= 6) return 95;
  if (loopPath.length === 5) return 90;
  if (loopPath.length === 4) return 85;
  if (loopPath.length === 3) return 75;
  return 0;
}

export default function FraudPage() {
  const [cycles, setCycles] = useState([]);
  const [logs, setLogs] = useState([]);
  const [tab, setTab] = useState('cycles');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    Promise.all([fetchFraudCycles(), fetchFraudLogs()])
      .then(([c, l]) => {
        const rawCycles = c?.cycles || c || [];
        const rawLogs = l?.logs || l || [];

        const normalizedCycles = rawCycles
          .map((cycle) => {
            const loopPath = getCyclePath(cycle);
            const tradePath = getTradePath(cycle);

            return {
              ...cycle,
              trade_id: getTradeId(cycle),
              stock: getStock(cycle),
              loopPath,
              tradePath,
              depth: getDepth(cycle, loopPath, tradePath),
              confidence: getConfidence(cycle, loopPath),
            };
          })
          .filter((cycle) => cycle.loopPath.length >= 3);

        setCycles(normalizedCycles);
        setLogs(Array.isArray(rawLogs) ? rawLogs : []);
        setLoading(false);
      })
      .catch(() => setLoading(false));
  }, []);

  const riskColor = (s) => (s >= 70 ? '#ef4444' : s >= 40 ? '#f59e0b' : '#a3e635');

  return (
    <div style={{ background: '#080808', minHeight: '100vh', padding: 32 }} className="grid-bg">
      <div style={{ maxWidth: 1200, margin: '0 auto' }}>
        <div style={{ marginBottom: 32 }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 8 }}>
            <div className="blink" style={{ width: 8, height: 8, borderRadius: '50%', background: '#ef4444' }} />
            <span style={{ color: '#ef4444', fontSize: 12, fontWeight: 700, letterSpacing: '0.12em' }}>
              FRAUD ENGINE ACTIVE
            </span>
          </div>
          <h1 style={{ fontSize: 28, fontWeight: 800, letterSpacing: '-0.02em' }}>
            Circular Trading <span style={{ color: '#ef4444', textShadow: '0 0 20px rgba(239,68,68,0.4)' }}>Detection</span>
          </h1>
          <p style={{ color: '#6b7280', marginTop: 8, fontSize: 14 }}>
            WITH RECURSIVE SQL engine scanning all trade cycles in real-time
          </p>
        </div>

        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3,1fr)', gap: 16, marginBottom: 28 }}>
          {[
            { label: 'Total Cycles', value: cycles.length, color: '#ef4444' },
            { label: 'Critical (≥70)', value: cycles.filter((c) => c.confidence >= 70).length, color: '#ef4444' },
            { label: 'Fraud Log Entries', value: logs.length, color: '#f59e0b' },
          ].map((s, i) => (
            <div key={i} className="glass" style={{ padding: 24 }}>
              <div style={{ color: '#6b7280', fontSize: 11, fontWeight: 600, letterSpacing: '0.08em', textTransform: 'uppercase', marginBottom: 8 }}>
                {s.label}
              </div>
              <div style={{ fontSize: 36, fontWeight: 900, color: s.color, textShadow: `0 0 16px ${s.color}44` }}>
                {s.value}
              </div>
            </div>
          ))}
        </div>

        <div style={{ display: 'flex', gap: 8, marginBottom: 20 }}>
          {['cycles', 'logs'].map((t) => (
            <button
              key={t}
              className={`btn-ghost ${tab === t ? 'active' : ''}`}
              onClick={() => setTab(t)}
              style={{ textTransform: 'capitalize' }}
            >
              {t === 'cycles' ? `🔁 Fraud Cycles (${cycles.length})` : `📋 Risk Logs (${logs.length})`}
            </button>
          ))}
        </div>

        {loading ? (
          <div style={{ textAlign: 'center', padding: 80, color: '#4b5563' }}>
            <div style={{ fontSize: 32, marginBottom: 12 }} className="neon">⟳</div>
            <div>Running recursive detection...</div>
          </div>
        ) : tab === 'cycles' ? (
          <div style={{ display: 'grid', gap: 16 }}>
            {cycles.length === 0 ? (
              <div className="glass" style={{ padding: 48, textAlign: 'center', color: '#6b7280' }}>
                <div style={{ fontSize: 32, marginBottom: 12 }}>✅</div>
                No fraud cycles detected yet. Run the dataset generator first.
              </div>
            ) : (
              cycles.map((cycle, i) => (
                <div key={i} className="glass card-hover fraud-pulse" style={{ padding: 24, borderColor: 'rgba(239,68,68,0.15)' }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 16 }}>
                    <div>
                      <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 6 }}>
                        <span style={{ color: '#ef4444', fontSize: 11, fontWeight: 700, letterSpacing: '0.1em' }}>
                          🔴 CYCLE #{i + 1}
                        </span>
                        <span style={{ background: 'rgba(239,68,68,0.12)', border: '1px solid rgba(239,68,68,0.2)', color: '#f87171', padding: '2px 10px', borderRadius: 999, fontSize: 11, fontWeight: 600 }}>
                          {cycle.loopPath.length} nodes
                        </span>
                      </div>

                      <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }}>
                        {cycle.loopPath.map((node, j, arr) => (
                          <React.Fragment key={j}>
                            <span
                              style={{
                                padding: '5px 12px',
                                borderRadius: 8,
                                fontSize: 13,
                                fontWeight: 600,
                                background: j === arr.length - 1 ? 'rgba(239,68,68,0.1)' : 'rgba(163,230,53,0.06)',
                                color: j === arr.length - 1 ? '#ef4444' : '#a3e635',
                                border: `1px solid ${j === arr.length - 1 ? 'rgba(239,68,68,0.25)' : 'rgba(163,230,53,0.15)'}`,
                              }}
                            >
                              T{node}
                            </span>
                            {j < arr.length - 1 && <span style={{ color: '#4b5563' }}>→</span>}
                          </React.Fragment>
                        ))}
                      </div>
                    </div>

                    <div style={{ textAlign: 'right' }}>
                      <div style={{ fontSize: 28, fontWeight: 900, color: riskColor(cycle.confidence), textShadow: `0 0 12px ${riskColor(cycle.confidence)}44` }}>
                        {cycle.confidence}
                      </div>
                      <div style={{ color: '#4b5563', fontSize: 11, fontWeight: 600 }}>CONFIDENCE</div>
                    </div>
                  </div>

                  {cycle.explanation && (
                    <div style={{ background: 'rgba(0,0,0,0.3)', borderRadius: 8, padding: '10px 14px', fontSize: 12, color: '#6b7280', borderLeft: '2px solid rgba(239,68,68,0.3)' }}>
                      {cycle.explanation}
                    </div>
                  )}

                  <div style={{ marginTop: 12, display: 'flex', gap: 20, flexWrap: 'wrap' }}>
                    <span style={{ color: '#4b5563', fontSize: 12 }}>
                      Trade ID: <span style={{ color: '#9ca3af' }}>#{cycle.trade_id}</span>
                    </span>
                    <span style={{ color: '#4b5563', fontSize: 12 }}>
                      Stock: <span style={{ color: '#9ca3af' }}>{cycle.stock}</span>
                    </span>
                    <span style={{ color: '#4b5563', fontSize: 12 }}>
                      Trade Path: <span style={{ color: '#9ca3af' }}>{cycle.tradePath.length ? cycle.tradePath.join(' → ') : '—'}</span>
                    </span>
                    <span style={{ color: '#4b5563', fontSize: 12 }}>
                      Depth: <span style={{ color: '#9ca3af' }}>{cycle.depth}</span>
                    </span>
                  </div>
                </div>
              ))
            )}
          </div>
        ) : (
          <div className="glass" style={{ overflow: 'hidden' }}>
            <table className="data-table">
              <thead>
                <tr>
                  <th>Trade ID</th>
                  <th>Risk Score</th>
                  <th>Label</th>
                  <th>Reason</th>
                  <th>Detected</th>
                </tr>
              </thead>
              <tbody>
                {logs.map((l, i) => {
                  const reason = l.reason || '';
                  const isAbnormal = reason.toLowerCase().includes('abnormal price movement');
                  return (
                    <tr key={i}>
                      <td style={{ fontFamily: 'monospace', color: '#4b5563' }}>#{l.trade_id}</td>
                      <td><span style={{ fontWeight: 700, color: riskColor(l.risk_score) }}>{l.risk_score}</span></td>
                      <td>
                        {l.risk_label ? (
                          <span className={`badge ${l.risk_score >= 70 ? 'badge-high' : l.risk_score >= 40 ? 'badge-medium' : 'badge-low'}`}>
                            {l.risk_label}
                          </span>
                        ) : '—'}
                      </td>
                      <td style={{ maxWidth: 300, color: isAbnormal ? '#f59e0b' : '#9ca3af' }}>{reason}</td>
                      <td style={{ color: '#4b5563', fontSize: 12 }}>
                        {l.detected_at ? new Date(l.detected_at).toLocaleString() : '—'}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}
